#!/usr/bin/env python3
"""Build findings.jsonl. Numbers are read from the intermediate JSON the analysis scripts wrote to $WORK, so nothing is
retyped except a few constants copied from a named source file (marked 'src:'). Evidence hashes are computed from disk
here (sha256 of the file as it exists now) except the two very large inputs, whose hashes were computed by the
streaming scripts (ix_extract.py, price_dispersion.py) in the same pass that read them.
Usage:  WORK=<dir with the *_result.json / _run*.json files> python make_findings.py"""
import json, os, hashlib
WORK = os.environ['WORK']
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.normpath(os.path.join(HERE, '..', '..', '..'))          # .../axm-tools
MAIN = os.path.join(ROOT, 'main')
BIG = {  # sha256 of very large inputs, computed by the scripts that streamed them (input_sha256 / sha256 fields)
    'sessions/public-tail-20260929/lanes/inferencex-history/imported-main/inferencex-2026-09-29.jsonl': '1eab076241673432f84802d83597161aeb31420c95a87b49ae4b64accf69bf2f',
    'sessions/public-tail-20260929/lanes/opencomputeprices/rows/prices.jsonl': '390b25b1b25d59631166dae6273ba7b04c4a8645191002eafafe865afaa73bd0',
}
def J(name): return json.load(open(os.path.join(WORK, name), encoding='utf-8'))
def sha(rel):
    if rel in BIG: return BIG[rel]
    p = os.path.join(ROOT, rel)
    h = hashlib.sha256()
    with open(p, 'rb') as f:
        for b in iter(lambda: f.read(1 << 22), b''): h.update(b)
    return h.hexdigest()
def ev(*rels): return [{'path': r, 'sha256': sha(r)} for r in rels]
R = 'main/hot-aisle/campaign/results/'
C = 'main/hot-aisle/campaign/'
S = 'sessions/public-tail-20260929/lanes/'
rows = []
def F(id, kind, cls, claim, numbers, evidence, producer, conditions, implication, confidence, confirm, window):
    rows.append(dict(id=id, kind=kind, evidence_class=cls, claim=claim, numbers=numbers, evidence=evidence, producer=producer,
                     window=window, conditions=conditions, implication_for_a_shop=implication, confidence=confidence, what_would_confirm=confirm))
r2 = J('_run2_cells.json'); D, E = r2['default'], r2['explore']
r3 = J('_run3_arms.json'); tk = J('_run3_tokens.json'); ut = J('_run3_util.json'); r1 = J('_run1_cells.json')
rd = lambda x, n=4: None if x is None else round(x, n)
# ---------------------------------------------------------------- T01 / T02 Run 2 forced vs auto
cells = []
for c, e in E.items():
    for base in (c, c.replace('-r0', '-r1')):
        if base in D and (base == c or c.startswith('cell-long')):
            d = D[base]
            cells.append({'cell': c.replace('cell-', '').replace('-r0', ''), 'auto_run': base.replace('cell-', ''), 'auto_req_s': rd(d['req_s']), 'forced_req_s': rd(e['req_s']), 'delta_pct': rd((e['req_s']/d['req_s']-1)*100, 1),
                          'ttft_p50_ms_auto_forced': [rd(d['ttft_p50'], 0), rd(e['ttft_p50'], 0)], 'ttft_p95_ms_auto_forced': [rd(d['ttft_p95'], 0), rd(e['ttft_p95'], 0)], 'ttft_p99_ms_auto_forced': [rd(d['ttft_p99'], 0), rd(e['ttft_p99'], 0)],
                          'e2e_p95_ms_auto_forced': [rd(d['e2e_p95'], 0), rd(e['e2e_p95'], 0)], 'peak_kv_pct_auto_forced': [d['peak_kv_pct'], e['peak_kv_pct']]})
F('T01', 'telemetry', 'measured', 'Run 2 (Llama-3.3-70B FP8, 1x MI300X, vLLM 0.30.0): forcing --attention-backend ROCM_AITER_FA over the auto-selected ROCM_ATTN changes throughput per cell as listed; the 46% headline is one cell and the sign and size depend on cell.',
  {'cells': cells, 'note': 'auto has two repeats for long cells (r0, r1) and one for short cells; forced has one repeat (r0). Repeat-to-repeat spread on auto: long-c8 0.2179 vs 0.2157 req/s, long-c32 0.3032 vs 0.3016 req/s.', 'unit_req_s': 'requests/second', 'prompts_per_cell': {'long': '16 at c1, 64 at c8, 128 at c32', 'short': '16 at c1, 64 at c8, 128 at c32, 256 at c64'}},
  ev(R+'run2-hotaisle-mi300x/arm-log.txt', R+'run2-explore-hotaisle-mi300x/arm-log.txt', R+'run2-hotaisle-mi300x/cell-long-c32-r0.json', R+'run2-hotaisle-mi300x/cell-long-c32-r1.json', R+'run2-explore-hotaisle-mi300x/cell-long-c32-r0.json', R+'run2-hotaisle-mi300x/serve.log', R+'run2-explore-hotaisle-mi300x/serve.log', R+'run2-explore-hotaisle-mi300x/env.json', R+'run2-hotaisle-mi300x/env.json'),
  'ours', 'Same host enc1-gpuvm002, same image vllm/vllm-openai-rocm sha256:2e7da1ad..., same flags except --attention-backend. Auto arm ran 19:11-22:00 UTC, forced arm 22:01-22:26 UTC on 2026-09-23 (about 2.5 h later). Forced arm is post-hoc and unregistered (EXPLORE.md).', 'Attention backend is a per-workload choice: measure both on your own prompt shape before fixing it. The gain is largest where the KV cache is nearly full or prompts are long (long c8 +28%, long c32 +46%) and small on short prompts (+2.5% to +11%).', 'high for the deltas on these cells (auto repeats agree within 1%); low that they transfer', 'A frozen confirmation run: 3 repeats of forced and auto interleaved in one session, on the same cells.', '2026-09-23 19:17-22:26 UTC')
F('T02', 'telemetry', 'measured', 'In Run 2 the forced backend did not leave c1 unchanged in latency: time to first token fell 12.5% (long) and 7.7% (short) at c1 while requests/second stayed within 0.4%.',
  {'long_c1_ttft_p50_ms_auto_r0_r1_forced': [D['cell-long-c1-r0']['ttft_p50'], D['cell-long-c1-r1']['ttft_p50'], E['cell-long-c1-r0']['ttft_p50']], 'short_c1_ttft_p50_ms_auto_forced': [D['cell-short-c1-r0']['ttft_p50'], E['cell-short-c1-r0']['ttft_p50']],
   'long_c1_req_s_auto_r0_r1_forced': [D['cell-long-c1-r0']['req_s'], D['cell-long-c1-r1']['req_s'], E['cell-long-c1-r0']['req_s']], 'long_c32_ttft_p95_ms_auto_r0_forced': [D['cell-long-c32-r0']['ttft_p95'], E['cell-long-c32-r0']['ttft_p95']], 'long_c32_ttft_p99_ms_auto_r0_forced': [D['cell-long-c32-r0']['ttft_p99'], E['cell-long-c32-r0']['ttft_p99']]},
  ev(R+'run2-hotaisle-mi300x/cell-long-c1-r0.json', R+'run2-hotaisle-mi300x/cell-long-c1-r1.json', R+'run2-explore-hotaisle-mi300x/cell-long-c1-r0.json', R+'run2-hotaisle-mi300x/cell-short-c1-r0.json', R+'run2-explore-hotaisle-mi300x/cell-short-c1-r0.json'),
  'ours', 'c1 cells have 16 prompts, so p95 and p99 sit at the maximum (DISCLOSURES).', 'DISCLOSURES says c1 was unchanged; that holds for throughput, not for first-token latency. Interactive single-stream users see the backend even when batch throughput does not move.', 'medium (16 prompts per c1 cell, one forced repeat)', 'Repeat c1 with at least 200 prompts, forced and auto interleaved.', '2026-09-23')
# ---------------------------------------------------------------- T03 Run 3 forced vs auto
a0, a1, n0 = r3['run3-scored-a-t0'], r3['run3-scored-a-t1'], r3['run3-scored-n-t0']
F('T03', 'telemetry', 'measured', 'Run 3 (Qwen3-Coder-30B-A3B FP8, one hour of Azure code trace, 8,622 requests): on the short-prompt MoE the forced ROCM_AITER_FA arm is worse than auto on every latency percentile and accepted count; its 7 failures are client-side concurrency-limit events, not server errors.',
  {'ttft_ms_p50_p95_p99_from_send': {'A/T0 auto ROCM_ATTN': [rd(a0['ttft_from_send_ms']['50'], 1), rd(a0['ttft_from_send_ms']['95'], 1), rd(a0['ttft_from_send_ms']['99'], 1)], 'A/T1 forced ROCM_AITER_FA': [rd(a1['ttft_from_send_ms']['50'], 1), rd(a1['ttft_from_send_ms']['95'], 1), rd(a1['ttft_from_send_ms']['99'], 1)]},
   'ttft_ms_p50_p95_p99_from_scheduled_arrival': {'A/T0': [rd(a0['ttft_ms']['50'], 1), rd(a0['ttft_ms']['95'], 1), rd(a0['ttft_ms']['99'], 1)], 'A/T1': [rd(a1['ttft_ms']['50'], 1), rd(a1['ttft_ms']['95'], 1), rd(a1['ttft_ms']['99'], 1)]},
   'p99_ratio_forced_over_auto': rd(a1['ttft_from_send_ms']['99']/a0['ttft_from_send_ms']['99'], 3), 'p95_ratio': rd(a1['ttft_from_send_ms']['95']/a0['ttft_from_send_ms']['95'], 3),
   'accepted_auto_forced': [a0['accepted'], a1['accepted']], 'accepted_delta_pct': rd((a1['accepted']/a0['accepted']-1)*100, 2), 'correct_auto_forced': [a0['correct'], a1['correct']],
   'failed_forced': a1['errors'], 'failed_error_string': 'client_concurrency_limit x7 at request_index 2389-2430, end_ts == scheduled_ts', 'e2e_p95_ms_from_scheduled_auto_forced': [rd(a0['e2e_ms']['95'], 0), rd(a1['e2e_ms']['95'], 0)]},
  ev(R+'run3-scored-a-t0/replay/requests.jsonl', R+'run3-scored-a-t1/replay/requests.jsonl', R+'run3-scored-a-t0/detailed.json', R+'run3-scored-a-t1/detailed.json', R+'run3-scored-a-t0/grade/evaluation.json', R+'run3-scored-a-t1/grade/evaluation.json', R+'run3-scored-a-t1/serve.log'),
  'ours', 'One run per arm on one seat (enc1-gpuvm004), A/T0 00:45-01:45Z then A/T1 01:49-02:49Z on 2026-09-24. Client cap is 256 workers (load string workers=256).', 'Do not carry a tuning flag between workloads: on this workload forcing the vendor attention backend doubled p99 first-token latency (ratio shown) for no throughput gain. Also check whether a reported failure count is the server or your own load generator.', 'medium (single run; p99 of 8,622 is about 86 requests)', 'Three interleaved repeats per tier; raise the client worker cap above the burst peak so the 7 dropped requests are not confounded.', '2026-09-24 00:45-02:49 UTC')
# ---------------------------------------------------------------- T04 KV overload
def cell(c): return D[c]
F('T04', 'telemetry', 'measured', 'Run 2 KV-cache cells: long c32 already sits at 92% KV usage (32 x 8,704 tokens = 278,528 of a 300,192-token cache); c64 and c128 are past capacity, and doubling concurrency from c32 to c64 halves throughput and multiplies median first-token latency by 15.7. c64 and c128 measure overload, not capacity.',
  {'kv_cache_tokens_auto': 300192, 'kv_cache_tokens_forced': 299440, 'tokens_in_flight_by_construction_long': {'c8': 69632, 'c32': 278528, 'c64': 557056, 'c128': 1114112},
   'long_r0': {c: {'req_s': rd(cell('cell-long-'+c+'-r0')['req_s']), 'ttft_p50_s': rd(cell('cell-long-'+c+'-r0')['ttft_p50']/1000, 1), 'ttft_p95_s': rd(cell('cell-long-'+c+'-r0')['ttft_p95']/1000, 1), 'e2e_p50_s': rd(cell('cell-long-'+c+'-r0')['e2e_p50']/1000, 1), 'peak_kv_pct': cell('cell-long-'+c+'-r0')['peak_kv_pct'], 'max_waiting': cell('cell-long-'+c+'-r0')['max_waiting'], 'max_running': cell('cell-long-'+c+'-r0')['max_running'], 'duration_s': rd(cell('cell-long-'+c+'-r0')['dur_s'], 0)} for c in ('c1', 'c8', 'c32', 'c64', 'c128')},
   'throughput_c64_over_c32': rd(D['cell-long-c64-r0']['req_s']/D['cell-long-c32-r0']['req_s'], 3), 'throughput_c128_over_c64': rd(D['cell-long-c128-r0']['req_s']/D['cell-long-c64-r0']['req_s'], 3),
   'ttft_p50_c64_over_c32': rd(D['cell-long-c64-r0']['ttft_p50']/D['cell-long-c32-r0']['ttft_p50'], 1), 'preemption_lines_in_serve_log': 0,
   'short_c64_peak_kv_pct': D['cell-short-c64-r0']['peak_kv_pct']},
  ev(R+'run2-hotaisle-mi300x/serve.log', R+'run2-hotaisle-mi300x/arm-log.txt', R+'run2-hotaisle-mi300x/cell-long-c32-r0.json', R+'run2-hotaisle-mi300x/cell-long-c64-r0.json', R+'run2-hotaisle-mi300x/cell-long-c128-r0.json', C+'DISCLOSURES.md'),
  'ours', 'Peaks are read from 10-second vLLM log ticks ("GPU KV cache usage"), attributed to cells by arm-log start stamps (a stamp is written at cell start: next stamp minus this stamp equals duration plus about 15 s). max_running of 36 at c64/c128 is the KV-limited steady concurrency. DISCLOSURES calls c64/c128 overload; the c32 saturation is not stated there. Preemption count is not measured: vLLM does not log it at INFO and no metrics were scraped.', 'Size max concurrency from tokens in flight against the cache, not from GPU utilisation: past the cache limit you pay 2x the concurrency for half the throughput. Any tuning number taken at c32 on this workload is a near-saturated cell.', 'high for KV peaks and the throughput collapse; preemption itself unmeasured', 'Scrape vllm:num_preemptions_total and KV usage each second during the cells; repeat c32/c48/c64.', '2026-09-23 19:17-22:00 UTC')
